<script setup>
import {computed,ref} from 'vue'
import {useData} from 'vitepress'
import {products,connectorName,connectorNote,connectorHref,statusLabels} from '../data/connectors.mjs'
const props=defineProps({compact:Boolean})
const {frontmatter}=useData(),locale=computed(()=>frontmatter.value.locale==='en'?'en':'zh'),english=computed(()=>locale.value==='en')
const role=ref('ALL'),status=ref('ALL'),family=ref('ALL'),query=ref('')
const families={DOMESTIC:['信创数据库','Domestic databases'],RELATIONAL:['其他关系数据库','Other relational databases'],ANALYTICS:['分析系统','Analytics'],MESSAGING:['消息系统','Messaging']}
const priority=['MYSQL','GAUSS_POSTGRESQL','DM','KINGBASE','GBASE_8C','OCEANBASE','POSTGRESQL','CLICKHOUSE','DORIS','KAFKA','PULSAR']
const rows=computed(()=>products.map(product=>({...product,entries:product.entries.filter(row=>(role.value==='ALL'||(role.value==='BOTH'?product.entries.every(e=>e.status!=='PLANNED')&&product.entries.length>1:row.role===role.value))&&(status.value==='ALL'||row.status===status.value))})).filter(p=>p.entries.length&&(family.value==='ALL'||p.family===family.value)&&`${connectorName(p.id,locale.value)} ${p.id} ${families[p.family].join(' ')} ${p.family==='DOMESTIC'?'信创 国产':''}`.toLowerCase().includes(query.value.trim().toLowerCase())).sort((a,b)=>(priority.includes(a.id)?priority.indexOf(a.id):100)-(priority.includes(b.id)?priority.indexOf(b.id):100)))
const visible=computed(()=>props.compact?rows.value.slice(0,8):rows.value)
function reset(){role.value='ALL';status.value='ALL';family.value='ALL';query.value=''}
</script>
<template>
  <div class="connector-directory" :class="{compact}">
    <div class="catalog-controls">
      <label>{{english?'Direction':'连接方向'}}<select v-model="role"><option value="ALL">{{english?'All directions':'全部方向'}}</option><option value="SOURCE">{{english?'Source':'采集源'}}</option><option value="SINK">{{english?'Sink':'同步目标'}}</option><option value="BOTH">{{english?'Source & Sink':'源与目标均有实现'}}</option></select></label>
      <label>{{english?'Status':'支持状态'}}<select v-model="status"><option value="ALL">{{english?'All statuses':'全部状态'}}</option><option v-for="(label,key) in statusLabels" :key="key" :value="key">{{label[english?1:0]}}</option></select></label>
      <label>{{english?'Category':'系统类型'}}<select v-model="family"><option value="ALL">{{english?'All categories':'全部类型'}}</option><option v-for="(label,key) in families" :key="key" :value="key">{{label[english?1:0]}}</option></select></label>
      <label class="grow">{{english?'Find a connector':'查找连接器'}}<input v-model="query" type="search" :placeholder="english?'MySQL, PostgreSQL, DM…':'MySQL、达梦、金仓…'"></label>
    </div>
    <p class="directory-summary" aria-live="polite">{{rows.length}} {{english?'products · status is specific to each direction and profile':'种产品 · 按连接方向及指定环境分别标注状态'}}<span v-if="compact&&rows.length>visible.length">{{english?' · showing the first 8':' · 显示前 8 项'}}</span></p>
    <div class="connector-products">
      <article v-for="product in visible" :key="product.id" class="connector-product">
        <div class="product-name"><span class="connector-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/></svg></span><div><component :is="compact?'h3':'h2'">{{connectorName(product.id,locale)}}</component><small>{{families[product.family][english?1:0]}}</small></div></div>
        <div v-for="entry in product.entries" :key="entry.role" class="connector-profile"><div class="profile-heading"><strong>{{entry.role==='SOURCE'?(english?'Source':'采集源'):(english?'Sink':'同步目标')}}</strong><span class="support-status" :class="entry.status.toLowerCase()">{{statusLabels[entry.status][english?1:0]}}</span></div><p>{{connectorNote(entry,locale)}}</p><a :href="connectorHref(entry,locale)">{{entry.status==='PLANNED'?(english?'View plan':'查看规划'):(english?'Profile & requirements':'版本与使用条件')}} →</a></div>
      </article>
    </div>
    <div v-if="!rows.length" class="directory-empty"><p>{{english?'No matching profiles. Try another direction or category.':'没有匹配项，请调整连接方向或系统类型。'}}</p><button @click="reset">{{english?'Reset filters':'重置筛选'}}</button></div>
    <p v-if="compact" class="directory-more"><a :href="`/docs/${locale}/start/connectors.html`">{{english?'Browse every connector and version profile':'查看全部连接器与版本范围'}} →</a></p>
  </div>
</template>
<style scoped>
.connector-directory{margin-top:22px}.directory-summary{font-size:12px;color:var(--muted);margin:14px 0 20px!important}.connector-products{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.connector-product{border:1px solid var(--line);border-radius:8px;padding:22px;min-width:0;background:var(--canvas)}.product-name{display:flex;gap:12px;align-items:center;margin-bottom:20px}.product-name :is(h2,h3){font-size:16px;margin:0!important;border:0!important;padding:0!important;line-height:1.5}.product-name small{font-size:11px;color:var(--muted)}.connector-mark{width:32px;height:32px;color:var(--blue);flex:none}.connector-mark svg{width:100%;height:100%}.connector-profile+.connector-profile{border-top:1px solid var(--line);padding-top:17px;margin-top:17px}.profile-heading{display:flex;gap:10px;justify-content:space-between;align-items:baseline;flex-wrap:wrap}.profile-heading>strong{font-size:11px;font-weight:550}.support-status{font-size:10px;line-height:1.6;display:inline-flex;align-items:center;gap:6px;color:var(--muted)}.support-status:before{content:'';width:5px;height:5px;border-radius:50%;background:currentColor;flex:none}.available{color:var(--green)}.partially_verified{color:var(--blue)}.experimental{color:var(--caution)}.connector-profile>p{font-size:12px;line-height:1.8;margin:9px 0!important;color:var(--muted)}.connector-profile>a,.directory-more>a{font-size:11px;color:var(--blue)}.directory-more{margin-top:24px!important;text-align:right}.directory-empty{border:1px dashed var(--line);padding:30px;text-align:center;color:var(--muted);font-size:13px}.directory-empty button{color:var(--blue);padding:10px}.compact .catalog-controls{flex-wrap:wrap}.compact .connector-products{grid-template-columns:repeat(4,minmax(0,1fr))}.compact .connector-product{padding:18px}.compact .product-name{align-items:start;gap:9px;margin-bottom:14px}.compact .product-name :is(h2,h3){font-size:14px}.compact .connector-mark{width:25px;height:25px}.compact .profile-heading{display:block}.compact .support-status{display:flex;margin-top:5px}.compact .connector-profile p{font-size:11px}.compact .product-name small{font-size:10px}
@media(max-width:1050px){.compact .connector-products{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.catalog-controls>label{flex:1 1 calc(50% - 10px);min-width:0}.catalog-controls>label:nth-child(3),.catalog-controls>.grow{flex-basis:100%}.catalog-controls select{max-width:100%;min-width:0}.connector-products,.compact .connector-products{grid-template-columns:1fr}.connector-product{padding:18px}.compact .profile-heading{display:flex}.compact .support-status{margin:0}.directory-summary{font-size:11px}.directory-more{text-align:left}}
</style>
